"""Generate current analytical report from calculated outputs."""
import json,csv
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
B=json.loads((ROOT/'results/model_results.json').read_text(encoding='utf-8'))
S=json.loads((ROOT/'data/cart_stock_distributions.json').read_text(encoding='utf-8'))
I=json.loads((ROOT/'data/model_inputs.json').read_text(encoding='utf-8'))
base=next(c for c in B['cases'] if c['id']=='ozon_stock_base')
def effect(s,h):return next(r for r in B['results'] if r['scenario']==s and r['hypothesis']==h)
def pp(v):return f'{v:+.4f}'.replace('.',',')
def pct(v):return f'{v:.2%}'.replace('.',',')

def leaders(scenario):
    rows=[r for r in B['results'] if r['scenario']==scenario]
    best=max(r['delta_pp'] for r in rows)
    return ', '.join(r['hypothesis'] for r in rows if abs(r['delta_pp']-best)<1e-10)

def threshold_description(row):
    if row.get('status')=='equal':return 'Равенство эффектов', 'Порог победы отсутствует'
    if not row['threshold']:return 'Нет пересечения', 'Порог победы отсутствует'
    value=float(row['threshold'])
    if row['within_case_bounds']=='True':location='Внутри границ'
    elif value<S['bounds']['lower_necessary']:location='Ниже нижней границы кейса'
    else:location='Выше верхней границы кейса'
    return pct(value),location

base_verdict='Лидер базового сценария: '+leaders('ozon_stock_base')+'.'
stock_cases=[c for c in B['cases'] if c['kind']=='stock']
h4_wins=sum(effect(c['id'],'H4')['delta_pp']>effect(c['id'],'H1')['delta_pp']+1e-10 for c in stock_cases)
ties=sum(abs(effect(c['id'],'H4')['delta_pp']-effect(c['id'],'H1')['delta_pp'])<1e-10 for c in stock_cases)
stock_verdict=f'H4 выше H1 в {h4_wins} из {len(stock_cases)} stock-сценариев; равенство в {ties}. Вывод относится только к текущим коэффициентам.'
L=['# Исправленная модель Ozon: размеры Корзин и порог H1/H4','',f"29.10.2026. {len(B['cases'])} сценариев × {len(I['hypotheses'])} самостоятельных альтернатив. Все эффекты — мысленные эксперименты, не результаты A/B-тестов. Исходная UX ICE не изменена.",'',
'## Исправление stock/flow','','11,17% в Taobao — пользователи с 14+ уникальными добавлениями за девять дней, а не остатком 40+ SKU. Прежний перенос долей в охват H1 отозван. Расчёт сценариев Ozon больше не читает Taobao: это проверено тестом с отсутствующим файлом. Исторические результаты сохранены с предупреждением в archive/taobao_projection_2026-10-29.','',
'Taobao остаётся отдельным анализом событий добавления. Наличие отдельного Избранного, поиска, фильтров и группировки в Корзине по предоставленному пользователем конкурентному анализу — качественный референс. Он не определяет охват, причинный uplift или штрафы Ozon; отдельная инструментальная проверка интерфейса Taobao не выполнена.','',
'## Распределения Корзин','','При целочисленном X≤300 и p=P(X≥40) медиана 24 требует p≤50%. Максимальное среднее при данном p ограничено 0,5×24+(0,5−p)×39+300p=31,5+261p. Из среднего 60 следует p≥19/174≈10,92%. Это необходимые математические границы для популяции измерения размеров, не доверительный интервал и не оценка реальной доли. Достижимость нижней границы зависит от определения медианы.','',
'| Доля 40+ | Среднее | Медиана | Максимум | Среднее среди 40+ |','|---:|---:|---:|---:|---:|']
for d in S['distributions']:L.append(f"| {d['large_share']:.0%} | 60 | 24 | 300 | {d['large_conditional_mean']:.2f} |")
L+=['','В каждом примере 10 000 условных пользователей: 51% имеют 24 SKU, часть — 39, остальные — соседние большие значения и хотя бы один — 300. Полные гистограммы в data/cart_stock_distributions.json и Excel. При 11% большие Корзины почти все имеют 299–300 SKU: допустимый, но крайний пример. Сценарии не имеют оценённых вероятностей. База 30% — удобная центральная иллюстрация, а не найденная оценка.','',
'Среднее и медиана кейса не задают распределение по всем DAU, посетителям и платформам. Модель явно предполагает перенос формы stock на модельную популяцию; в базе доля 40+ одинакова среди посетителей и непосетителей C. В отдельных стрессах доля среди посетителей C отличается в 0,5/1,4 раза при сохранении общих дневных охватов C65%/F13%. Поэтому ограничение 50% нельзя без этого допущения распространять на любую выборку активных посетителей.','',
'Совместные когорты: S1=(1−p)f, S2=pf, S3=p(1−f), S4=(1−p)(1−f). f=40% большого Избранного и независимость размеров C/F — допущения; f=20%/60% проверено отдельно. Владение хотя бы одним товаром F согласовано с 70% кейса, что отличается от большого Избранного.','',
'## Сравнение H1–H6','',f"Изменение глобальной дневной CR в процентных пунктах. Базовая CR0={pct(base['global_cr'])}, прежний контроль — {pct(effect('original','H1')['cr0'])}. Все H получают +{pct(I['uplift'])} относительной CR цели до штрафов {pct(base['behavior_penalty'])}/{pct(base['product_penalty'])} в базе. H1 охватывает {pct(base['h1_need'])} потребности/использования среди уже отобранных 40+ и посетителей C; размер не учитывается повторно.",'',
'| H | Исходный контроль | 11% больших C | 30% больших C | 49% больших C | Нарушаемые метрики в негативных стрессах |','|---|---:|---:|---:|---:|---|']
for r in [r for r in B['results'] if r['scenario']=='ozon_stock_base']:
 h=r['hypothesis'];v=[pp(effect(s,h)['delta_pp']) for s in ['original','stock_11','ozon_stock_base','stock_49']]
 bad=[label for k,label in [('guard_c','CR C'),('guard_f','CR F'),('guard_arpu','ARPU')] if any(not x[k] for x in B['results'] if x['hypothesis']==h and x['kind']=='negative')]
 L.append('| '+' | '.join([h,*v,' / '.join(bad) or 'Нет в сетке'])+' |')
L+=['','H6.1/H6.2/H6.3 — самостоятельные альтернативы, их эффекты нельзя складывать. Сравнение исходного и новых столбцов одновременно меняет сегментацию и global CR; разницу нельзя приписывать одному фактору.','',
'## Когда H1 обгоняет H4','',f"При CR0={pct(base['global_cr'])}, f={pct(base['fav_large_share'])}, базовой посещаемости по когортам и текущей матрице охвата H4:",'',
'| Потребность/использование H1 среди 40+ | Порог доли 40+ | Совместимость с границами кейса |','|---:|---:|---|']
with (ROOT/'results/h1_h4_crossover.csv').open(encoding='utf-8-sig') as f:cross=list(csv.DictReader(f))
selected=[x for x in cross if float(x['global_cr'])==base['global_cr'] and float(x['h4_reach_multiplier'])==1 and float(x['h1_conditional_need']) in [.4,.6,.8,1.]]
for x in selected:
    threshold,location=threshold_description(x)
    L.append(f"| {float(x['h1_conditional_need']):.0%} | {threshold} | {location} |")
L+=['','Числа в таблице рассчитаны по текущим входам. При найденном пересечении H1 выигрывает выше порога, на пороге равенство. Порог за пределами границ stock остаётся контрфактическим. «Нет пересечения» означает отсутствие смены лидера в допустимом для CR диапазоне; это не обязательно победа H4. «Равенство эффектов» не задаёт порог победы. Полная таблица проверяет CR12/15/18/20,1%, потребность25/40/60/80/100% и охват H4×0,75/1/1,25.','',
'## Сохранилось ли преимущество H4','',base_verdict,'',stock_verdict,'',
'| Доля больших Корзин | Лидер при текущих входах |','|---:|---|']
for c in stock_cases:L.append(f"| {pct(c['large_share'])} | {leaders(c['id'])} |")
L+=['','Результаты сценарные; реальный охват потребностей H1/H4 остаётся неизвестным.','',
'| H | Минимум по основной сетке, п.п. | Максимум, п.п. | Места | Все защитные метрики пройдены |','|---|---:|---:|---|---|']
for r in B['robustness']:L.append(f"| {r['hypothesis']} | {pp(r['min_delta_pp'])} | {pp(r['max_delta_pp'])} | {r['rank_min']}–{r['rank_max']} | {'Да' if r['all_guardrails_pass'] else 'Нет'} |")
L+=['','Основная сетка включает stock, осторожный/благоприятный, CR, пересечения, охваты, потребность, большое F и состав визитов. Отдельные негативные/нулевой исключены из таблицы устойчивости, но рассчитаны отдельно. Количество побед не является вероятностью успеха.','',
'## Защитные метрики и неизвестные','','Нулевой сценарий даёт нулевой эффект. Негативные стрессы могут нарушать CR Корзины, CR Избранного и ARPU даже при росте global CR. Все флаги сохранены в scenario_results.csv и Excel. ARPU — условный индекс, без прогноза рублей. GMV не подставляется вместо выручки.','',
'Неизвестны реальная доля 40+, состав по DAU/посетителям/платформам, связь размеров C/F, порог большого F, потребности и пересечения задач, причинный uplift, ущерб, реальная дневная CR, доход на покупателя и стоимость реализации. 20,1% не факт Ozon. DAU44 млн/MAU84 млн — масштаб марта2026; квартальные заказы — условный ориентир интенсивности, а не источник CR.','',
'## ICE и тезис для презентации','',f'Первоначальная UX ICE не изменена. ICE оценивала привлекательность H1 по UX-наблюдениям и экспертным оценкам; сценарная модель оценивает масштаб условного эффекта на всех пользователей. {base_verdict} {stock_verdict} Ни ICE, ни эта модель не являются проведённым A/B-тестом.','',
'## Проверки','','Исходный XLSX сохранён; все формулы «Расчёт» сравниваются с ним. Рабочий файл обновлён из существующей рабочей версии. Проверяются 45 исходных assertions, 35×8 совпадений Python/Excel, кеши, stock/flow, распределения, пороги, нулевые/отрицательные эффекты, уникальная аудитория и пересчёт без сырых данных. Настольный Excel, Colab и интерфейс Taobao здесь не запускались.']
old=json.loads((ROOT/'archive/taobao_projection_2026-10-29/model_results.json').read_text(encoding='utf-8'))
L+=['','## Изменение относительно отозванного переноса Taobao','','Одинаковая global CR0=20,1%; новый сценарий использует p=30%/f=40%. Это совокупная смена сегментации, а не выделенный причинный эффект одного параметра.','', '| H | Прежний Taobao-контроль, п.п. | Исправленный stock30%, п.п. |','|---|---:|---:|']
for h in ['H1','H2','H3','H4','H5','H6.1']:
 previous=next(r for r in old['results'] if r['scenario']=='taobao_control_201' and r['hypothesis']==h)
 L.append('| '+h+' | '+pp(previous['delta_pp'])+' | '+pp(effect('cr_201',h)['delta_pp'])+' |')
(ROOT/'docs/findings.md').write_text('\n'.join(L)+'\n',encoding='utf-8')
sources=json.loads((ROOT/'data/sources.json').read_text(encoding='utf-8'))
L=['# Источники и ограничения','','Ранее проверенные источники сохранены; новые размеры Корзин построены по синтетическому кейсу, а не получены из Taobao.']
for s in sources:L+=['','## '+s['title'],'',s['url'],'','Статус: '+s['status']+'; проверка '+s.get('checked','не указана'),'',s['facts'],'','Использование: '+s['use'],'','Ограничение: '+s['limitation']]
(ROOT/'docs/sources.md').write_text('\n'.join(L)+'\n',encoding='utf-8')
print('Updated findings and sources')
